        [215155] = "Навчить вас, як зробити загартований шолом із запереченням перешкод",
        [215156] = "Навчить вас, як зробити гіперпровідний Goldwap",
        [215163] = "Навчає, як варити зілля омолодження з легким опроміненням.",
        [215168] = "Зменшена, але не менш смертельна версія складнішого аналога для тих, кому бракує компетентності, але є багато впевненості.",
        [215367] = "Навчає, як створити згусток ледь сяючої шкіри. ",
        [215368] = "Навчає, як створити котушку гіперпровідної аркано-нитки. ",
        [215369] = "Навчить вас, як шити Шнур Заклинача.",
        [215370] = "Навчить вас, як шити Мантію Заклинателя.",
        [215373] = "Знайдений на острові Терамор, де його власник загинув у битві з кровожерливою ордою орків.",
        [215374] = "Меч, що передавався з покоління у покоління в шляхетному роді Лордерона. Вважався давно втраченим у болотах навколо Кіросса разом з останнім воїном, що володів ним.",
        [215375] = "Блискуче розуміння тактики ведення бою власниці цього посоха могло зрівнятися лише з її вражаючими навичками володіння кригою і полум'ям",
        [215376] = "Вкритий засохлими шматками панцирів комах.",
        [215383] = "Навчить вас, як зробити світловідбиваючу мозкову клітку з справжнього срібла.",
        [215384] = "Навчить вас, як виготовляти срібні тарілки з низьким фоном.",
        [215422] = "Навчить вас, як створити світний гіперпровідний лускатий кофі.",
        [215423] = "Навчає, як створити капюшон гнейропровідного каналізатора.",
        [215424] = "Навчає, як створити радіаційно-стійкий капюшон з луски.",
        [215429] = "Навчить вас, як зробити набір полірованих шестерень зі справжнього срібла.",
        [215431] = "Навчає, як зробити пучок високопотужних радіаційних бомб.",
        [215432] = "Навчить вас, як робити радіаційні бомби Ez-Thro.",
        [215433] = "Навчає, як дистилювати флакон ізолюючого гніодину.",
        [215434] = "Навчає, як дистилювати флакон ізолюючого гніодину.",
        [215441] = "Цей вишуканий бойовий молот має штамп із емблемою Срібної Руки.",
        [215443] = "Залишки розбитої кулі слабко світяться та теплі на дотик.",
        [215456] = "Я ж тобі казав.",
        [215458] = "Серйозно, НЕ намагайтеся відкрити останню коробку. Ви вже отримали те, що хотіли.",
        [215459] = "Зупинись зараз. Це твоє останнє попередження.",
        [215460] = "УВАГА! Коробку поруч із цією запискою ніколи не можна відкривати.",
        [215468] = "Лист зім'ятий, на ньому є плями засохлої крові.",
        [215683] = "Теорії походження та використання елементальної магії. Чудове доповнення до колекції будь-якої бібліотеки.",
        [215815] = "Вступний посібник із захисної магії та бар'єрів. Чудове доповнення до колекції будь-якої бібліотеки.",
        [215816] = "Неповна теза, яка стверджує, що павуки нешкідливі, але тим не менш є чудовим доповненням до колекції будь-якої бібліотеки.",
        [215817] = "Дивний текст, що захищає демонів, проте чудове доповнення до колекції будь-якої бібліотеки.",
        [215820] = "Історії, достатньо страшні, щоб налякати навіть найвитриваліших воїнів. Чудове доповнення до колекції будь-якої бібліотеки.",
        [215822] = "Дивні уривки тьмяні, але певною мірою читабельні, незважаючи на пошкодження водою. Чудове доповнення до колекції будь-якої бібліотеки.",
        [215824] = "Містить корисні поради щодо того, як захистити реактиви від домашніх бісів. Чудове доповнення до колекції будь-якої бібліотеки.",
        [216491] = "Вантаж деревини з Тернистої Долини, який може бути корисним для вашої фракції в Араті-Хайлендс.",
        [216606] = "Навчає вас новій здатності гравіювання.",
        [216619] = "Старі добрі родзинки та арахіс... та багато іншого!",
        [216635] = "Це, здається, відповідає опису порожнечного ядра, яке потрібне Вірдалу, але воно, схоже, абсолютно інертне. Має бути спосіб його перезарядити...",
        [216636] = "Цей об'єкт ніби поглинає все навколишнє світло та тепло. Він дуже холодний на дотик.",
        [216637] = "Комусь десь це може здатися корисним, але тобі це здається просто мотлохом.",
        [216645] = "Темна енергія пронизує цю крихітну плавучу частинку енергії. Хто знає, яку дивовижну магію вона може створювати?",
