        [220167] = "Могильний пил з місця спочинку вбитого найдорожчими людьми...",
        [220168] = "Еліксир вогню, створений твердими руками та нестійким розумом...",
        [220169] = "Символ віри, подарований людиною з нещодавно відкритою метою...",
        [220217] = "Навчає вас новій здатності гравіювання.",
        [220345] = "Описує різноманітні потужні ритуали з кров’ю. Спірне доповнення до колекції будь-якої бібліотеки.",
        [220346] = "Вкрита нерозбірливими нотатками та схемами, нашкрябаними невпевненою рукою. Вона все ще могла б стати гідним доповненням до колекції будь-якої бібліотеки.",
        [220347] = "Слова пливуть по сторінці, не піддаючись спробам їх прочитати. Загадкове доповнення до колекції будь-якої бібліотеки.",
        [220348] = "Посібник з ролі елементарної магії у ввічливому суспільстві Високонароджених. Чудове доповнення до колекції будь-якої бібліотеки.",
        [220349] = "Міцні архітектурні прийоми, здатні витримати всі, окрім найкатастрофічніших лих. Чудове доповнення до колекції будь-якої бібліотеки.",
        [220350] = "Нотатки про властивості різних токсинів та отрут, що впливають на свідомість. Чудове доповнення до колекції будь-якої бібліотеки.",
        [220351] = "Каламутна суміш. Дивний нечесний вплив заплямує інакше впізнавану магію.",
        [220352] = "Гномьї методи застосування магії в металургії, гірничій справі та важкій промисловості. Інформативне, хоч і похмуре, доповнення до колекції будь-якої бібліотеки.",
        [220353] = "Довоєнна колекція заклять та таємних теорій, які значною мірою вийшли з сучасного ужитку. Чудове доповнення до колекції будь-якої бібліотеки.",
