        [238789] = "Навчає, як створити напівбезпечний транспортер: Новий Авалон.",
        [238794] = "Можливо, голодування не таке вже й погане.",
        [238797] = "З осколка пульсує сильна енергія феї.",
        [238798] = "З їдкого липкого матеріалу сочиться слабка енергія феєрії.",
        [238802] = "Від амулета виходить слабка заспокійлива енергія.",
        [238811] = "Свіжий з поля.",
        [238830] = "Використовується найлінивішими фермерами для контролю врожаю, не виходячи з дому.",
        [238831] = "Це просто звичайна мотузка.",
        [238899] = "Ваші рибальські навички недостатньо високі, щоб розпізнати більшість цих риб, але, на щастя, це не ваша проблема.",
        [238927] = "Навчає, як виготовити Червоний сагайдак.",
        [238928] = "Навчає, як створити червоний підсумок для боєприпасів.",
        [238935] = "Якщо ви відріжете зелені частини, хто про це дізнається?",
        [238985] = "Доставте до Червоного квартирмейстера, щоб завершити завдання «Доведіть свою цінність».",
        [239006] = "З колись прекрасної квітки слабо випромінюється збочена енергія.",
        [239013] = "Леза Світла, справді.",
        [239016] = "Зазвичай використовується хрестоносцями для захисту від невдачі. Зручно, що він також корисний для приготування їжі.",
        [239017] = "Суворо регульований товар; купувати чи продавати безпосередньо було б нерозумно. Кухарі бажають його під час приготування святкових страв.",
        [239119] = "Благословенна стріла, що вражає наших ворогів.",
        [239149] = "Навчає, як створити рюкзак хрестоносця.",
        [239150] = "Навчає, як створити ткану сумку Багряного Світанку.",
        [239218] = "Цей документ написаний недбало скорочено, але те, що ви можете зрозуміти, свідчить про те, що ці плани та нотатки до проекту є результатом роботи справжнього генія ремісника.",
        [239222] = "Навчить вас, як створити спливаючий кущ.",
        [239223] = "Неймовірно переконливо в контексті опери чи п'єси.",
        [239225] = "Ви можете лише уявити собі задоволення від написання власного підпису за допомогою цього.",
        [239246] = "Список пунктів, нашвидкуруч записаних щоразу, коли вони спадали на думку автору.",
        [239292] = "Містить зібрані думки та праці Франклорна Форджрайта.",
        [239302] = "Щільний шкіряний ремінь із важкою сталевою пряжкою. Справжній шедевр серед ременів, який може бути зіпсований необдуманими маніпуляціями.",
        [239545] = "Ямкова ерозія показує, де ця кам'яна ікона піддалася багаторічному впливу вивітрювання.",
        [239698] = "Невеликі шматочки тканини та ниток, які таємничим чином притягували до ткацького верстата хрестоносців. Очевидно, їх використовували під час пошиття священних риз.",
        [239704] = "Від зношеного ельфійського амулета виходить дивна енергія.",
        [239764] = "Яскраво-червоний барвник, який видобувається з усього, крім пелюсток щойно розквітлого листя листя.",
        [240846] = "Сміття для однієї людини — скарб для іншої, подобається їй це чи ні!",
        [240945] = "Незважаючи на те, що пиріг був розрізаний на три частини однакового розміру, тобі якимось чином вдалося отримати найменший шматочок.",
        [241191] = "Навчає, як накласти на зброю перманентні чари, щоб час від часу благословляти власника неймовірною силою.",
        [241195] = "Навчає, як накласти на дворучну зброю ближнього бою назавжди чари, щоб періодично благословляти власника посиленою силою заклять.",
        [241201] = "Навчає, як накласти на зброю ближнього бою постійні чари, щоб періодично благословляти власника посиленою силою заклять.",
        [241651] = "Навчає, як виготовити Зілля знебарвлення.",
        [241655] = "Справді огидне зілля.",
        [241656] = "Справді огидне зілля.",
        [242018] = "Надзвичайно чудова квітка, враховуючи регіон, з якого вона походить. Вона здатна процвітати, незважаючи на чуму.",
        [242224] = "Можливо, не найкращий контейнер, який можна було б вибрати для такої ситуації.",
        [242266] = "Від кірки до кірки заповнена ретельною документацією всього, що пов'язано з магічними оберегами. Цікаво, що книга має ледь помітне сяйво.",
        [242267] = "Самореклама автобіографії, написаної автором, надто неактуальним, щоб його ім'я було названо. Цікаво, що книга також сповнена чарівної сили привернути увагу.",
        [242268] = "Цікава коротка історія, яка швидко перетворюється на божевілля, перш ніж досягти кульмінації, даючи антагоністу все, чого він хоче. Цікаво, що книга виблискує силою.",
        [242361] = "Навчає, як накласти назавжди чари на дворучну зброю ближнього бою, щоб періодично благословляти власника величезною силою.",
        [242363] = "Читаючи це, у вас виникло більше запитань, ніж відповідей. Про що взагалі була ця книга? І чому вона сповнена великого передчуття?",
        [243203] = "Шматок кришталю розміром з кулак з блідо-блакитним блиском.",
        [243299] = "Не витрачайте все в одному місці.",
        [245983] = "Потерта та відшліфована від часу, ця деревина капу має вирізьблений на її поверхні відбиток ведмежої лапи. У вас є сильне бажання передати це іншій спорідненій душі, яка цього потребує.",
        [246213] = "Вантаж деревини з Тернистої Долини, який може бути корисним для вашої фракції в Араті-Хайлендс.",
        [246885] = "Можна сказати, що ця лялька була дуже улюбленою.",
        [246888] = "Шматок кришталю розміром з кулак з блідо-блакитним блиском.",
        [247000] = "З цієї скелі піднімаються блискучі зелені пари. Мабуть, не варто часто торкатися її голою шкірою.",
        [247001] = "З цієї гілки піднімаються блискучі зелені пари. Її спалювання, ймовірно, призведе до виділення токсичного диму.",
        [247786] = "Доступно у чарівних продавців.",
        [247839] = "Лише трохи погризли.",
        [247840] = "Пояснює, як вести майнінг, використовуючи лише десятьсот найпоширеніших слів.",
        [247841] = "Інструкція зі збору дикорослих трав.",
        [247846] = "Книжка з картинками, що документує, як збирати шкури тварин.",
        [247876] = "Навчає, як викликати цього супутника.",
        [247883] = "Слабку магію всередині можна витягти за допомогою навички Розчарування.",
        [247886] = "Кожна книжка в цьому мішку — дитяча книжка з картинками. Кобольди явно не вміють читати, але навіщо їм ці книжки?",
        [248001] = "У досить хорошому стані, як для кобольдів, які ним керували.",
        [248002] = "Ця книга у бездоганному стані.",
        [248003] = "Цей чудово ілюстрований буквар вкритий липкою павутиною, ніби хтось витягнув його з павутиння.",
        [248004] = "Колекція анотованих діаграм, що ілюструють принципи таємничої майстерності. Вона вкрита липкою павутиною.",
        [248206] = "Замовлення на виготовлення, що очікує на перевезення, перехоплене під час доставки. Можливо, ви можете стати засобом для його досягнення.",
        [248549] = "Довгоочікуваний вантаж, який так і не прибув до місця призначення. Деякі його припаси відсутні.",
