        [255731] = "Навчить вас, як зробити потужний припарку.",
        [255878] = "Воно гуде від сили. Тримаючи це, ви відчуваєте сміливість у своїй подорожі.",
        [255945] = "Всередині можна відчути присутність зла.",
        [256057] = "Неймовірно рідкісний кристал, що походить з іншого світу. Його численні способи використання тільки почали відкриватися.",
        [257029] = "Стара сумка, що містила кілька непереплетених книг з розсипчастого пергаменту.",
        [257126] = "У ньому є сяйво життя, але немає тепла.",
        [257348] = "Містить саму іскру творчості.",
        [257685] = "Вщерть переповнений тотемами, що використовуються кентаврами як валюта. Доставка цього одному з ворогуючих кланів неодмінно заслужить їхню прихильність.",
        [257808] = "Листи та посилки для доставки до Еверлука.",
        [257809] = "Листи та посилки для доставки на гору Хіджал.",
        [258296] = "Одна пляшечка цієї містичної води може викликати потік дощу.",
        [258526] = "Журнал наповнений інформацією про атмосферну погоду та етапи запуску ракет.",
        [258774] = "Нотатки написані різними кольорами чорнила, що свідчить про тривале навчання.",
        [259226] = "Просто залізна руда, хоча й пов'язана з духовним світом.",
        [259229] = "Виявляє примарні поклади заліза, перебуваючи у вашому інвентарі. Також служить звичайним вибором для видобутку!",
        [259461] = "О ні...",
        [259990] = "Це був перстень з бивня троля. Колись його явно дуже любили, але це було давно.",
        [260167] = "Напис на язичку черевика: ...16, 23...",
        [260237] = "Чи це справді кров занепалого бога, незрозуміло, але точно відомо, наскільки вона прагне вирватися з чаші.",
        [260244] = "Чи взагалі квілбор любить квіти?",
        [260245] = "Його краса разюче контрастує з садами, в яких він ріс.",
        [260247] = "Колись це було зачароване намисто, що підтримувало життя в садах Шен'драласа. Яка б магія в ньому не була, вона з того часу вичерпалася.",
        [260307] = "Ні снігу, ні дощу, ні спеки, ні нічної темряви...",
        [260347] = "Більшість сторінок відсутні.",
        [260518] = "Висновки Гімаші щодо дренетисту; упорядковані та відредаговані для ясності.",
        [260784] = "Завдяки фірмовим вкладкам SAF-T SAF-T може роздавати динаміт усім своїм друзям!",
        [260792] = "Легко кидати, і SAF-T також!",
        [260793] = "Бомби марки SAF-T *майже* ніколи не вибухають у ваших руках (або лапах!)",
        [260796] = "Накладка SAF-T запобігає легким випадковим кидкам.",
        [260798] = "Якщо його легко кинути, це не SAF-T!",
        [260799] = "Ти знаєш, де твоя вівця?! SAF-T знає.",
        [260800] = "Гарантовано вибухне лише там, де це SAF!",
        [260801] = "Гарантовано не згорить!",
        [260802] = "Через мо мо тар!",
        [260803] = "Кому потрібна безпека, коли так легко кинути?",
        [260804] = "Додаткова підкладка для SAF-T!",
        [260805] = "С. А. Ф. Т. Б. О. М. Б. С. А. Ф. Т. Бомба.",
        [260806] = "SAF-T означає не бути спійманим.",
        [260808] = "Легкий у використанні та майже ніколи не дає пропусків запалювання!",
        [260809] = "Tru-Trigger вражає ворогів, а не ваших рук.",
        [260810] = "SAF-T на випадок, якщо вам потрібно буде стрибнути.",
        [260811] = "У ньому є все: гайковий ключ, розвідний ключ, молоток... навіть шахтарська кирка.",
        [260813] = "Запобігає випадковому контакту з киснем. Це не було б SAF (Security After Air).",
        [260814] = "SAF-T не щільний. Він розумний!",
        [260815] = "Упакуйте свої вибухівки в оболонки з торієвим покриттям EZ to Thro.",
        [260816] = "Будь-хто може використовувати гранати з EZ-Thro!",
        [260817] = "Отже, EZ, ви можете пройти крізь нього в темряві.",
        [260821] = "Не лише поєднання технологій Гоблінів та Гномів, а й поєднання планів корпорацій EZ-Thro та SAF-T. Хто знає, чи це взагалі спрацює?",
        [260823] = "Небезпечне поєднання інженерних технік гоблінів та гномів.",
        [260827] = "Використовується справжніми таємними агентами.",
        [260828] = "Ракета безпечно переміщена за допомогою SAF-T.",
        [260829] = "Корпорація EZ-Thro не несе відповідальності за магніти, що запобігають киданню гранат.",
        [260830] = "Телепорт до SAF-T!",
        [260880] = "Сяюча куля ніби дивиться на тебе, з тихою цікавістю стежить за твоїми рухами.",
        [260881] = "Поверхня цього предмета гладка на дотик, і від неї волосся на потилиці стає дибки, коли ви його тримаєте.",
        [260883] = "Цей об'єкт м'яко вібрує, постійно перебуваючи у стані вічного руху. Якщо спробувати утримати його нерухомо, сила, яку він чинить, значно зростає.",
        [262668] = "Безголовий вітер свистить м'яким холодом крізь зачаровані гілки.",
        [262766] = "Навчає, як викликати цього їздова тваринаа.",
        [262801] = "Прошита строкатою, але міцною шкірою.",
        [262887] = "Замовлення на виготовлення, що очікує на перевезення, перехоплене під час доставки. Можливо, ви можете стати засобом для його досягнення.",
        [262888] = "Замовлення на виготовлення, що очікує на перевезення, перехоплене під час доставки. Можливо, ви можете стати засобом для його досягнення.",
        [262889] = "Замовлення на виготовлення, що очікує на перевезення, перехоплене під час доставки. Можливо, ви можете стати засобом для його досягнення.",
