        [286280] = "Юний Артас має навчитися терпінню, щоб стримувати свою силу. Я молитимуся, щоб він одного дня навчився керувати обережно, а не силою.",
        [286283] = "Я мрію колись потрапити на пенсію у свій власний охайний маленький маєток, де мені будуть товариство собаки.",
        [286284] = "Бранн Бронзобородий був тут.",
        [286287] = "Іноді... мені хочеться, щоб хтось підійшов і просто міцно, довго мене обійняв.",
        [286288] = "Артасе, коханий мій, будь ласка, повернися до мене.",
        [286290] = "Послухай, маленький фонтанчик бажань. Ти віддаси мені всю свою силу, якщо знатимеш, що для тебе добре.",
