        [286299] = "Громе, спочивай спокійно, старий друже.",
        [286300] = "Це не має сенсу. Навіщо я кидаю монету у фонтан?",
        [286304] = "Шкода, що мій двоюрідний брат не займався нічим, крім як недбало тягав дрова...",
